package com.harsh.explore.streams;import java.util.Arrays;import java.util.List;import java.util.function.Consumer;import static java.lang.System.out;public class ConsumerExample {        static Consumer<String> strConsumer = (students)-> out.println(students);    public static void main(String[] args) {        List<String> students = Arrays.asList("Harsh","Dheeraj","Mithilesh","Pramod");        strConsumer.accept(String.valueOf(students));    }}